const rows = $input.first().json.rows;
const projectId = rows[0].project_id;

const scenes = rows.map(row => ({
  id: row.scene_id,
  scene_number: row.scene_number,
  title: row.scene_title,
  summary: row.summary,
  characters_present: JSON.parse(row.characters_present || '[]'),
  location: row.location,
  time_period: row.time_period,
  emotional_tone: row.emotional_tone,
  chapter_number: row.chapter_number
}));

// Build chronological validation prompt
const timelinePrompt = `Validate the chronological order and consistency of this novel's timeline:\n\nScenes in story order:\n${scenes.map((s, i) => `${i+1}. Ch${s.chapter_number} Scene${s.scene_number}: "${s.title}" | Location: ${s.location} | Time: ${s.time_period} | Characters: ${s.characters_present.join(', ')} | Tone: ${s.emotional_tone}`).join('\n')}\n\nCheck for:\n1. chronological_order: Are scenes in correct chronological order? Any flashbacks/flashforwards?
2. character_presence: Are characters present where they should be? No impossible appearances?
3. location_consistency: Do characters travel logically between locations?
4. time_gaps: Any suspicious time gaps or overlaps?
5. contradictions: Any factual contradictions between scenes?
6. suggested_fixes: Array of {issue, scene_ids, fix_description}
\nReturn as JSON with keys: is_valid, chronological_order, character_issues, location_issues, time_gaps, contradictions, suggested_fixes.
\nIMPORTANT: Return ONLY valid JSON.`;

return [{
  json: {
    project_id: projectId,
    scenes: scenes,
    timeline_prompt: timelinePrompt,
    total_scenes: scenes.length
  }
}];

const responseText = $input.first().json.response || '{}';
let validation = {};

try {
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    validation = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  validation = {
    is_valid: true,
    chronological_order: [],
    character_issues: [],
    location_issues: [],
    time_gaps: [],
    contradictions: [],
    suggested_fixes: []
  };
}

const projectId = $('Execute Logic').item.json.project_id;
const scenes = $('Execute Logic').item.json.scenes;

const totalIssues = (validation.character_issues || []).length + 
                    (validation.location_issues || []).length + 
                    (validation.time_gaps || []).length + 
                    (validation.contradictions || []).length;

return [{
  json: {
    project_id: projectId,
    validation: validation,
    is_valid: validation.is_valid !== false && totalIssues === 0,
    total_issues: totalIssues,
    issues_fixed: (validation.suggested_fixes || []).length
  }
}];

